create extension if not exists pgcrypto;
create table if not exists public.projects (id uuid primary key default gen_random_uuid(), name text not null check (char_length(name) between 1 and 80), description text not null default '', category text not null default 'Project', image_url text, status text not null default 'In progress', website_url text, repository_url text, is_featured boolean not null default false, display_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.guestbook (id uuid primary key default gen_random_uuid(), display_name text not null check (char_length(display_name) between 2 and 60), message text not null check (char_length(message) between 3 and 500), is_approved boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.page_views (id bigint generated always as identity primary key, page_path text not null, session_id uuid not null, referrer_domain text, created_at timestamptz not null default now());
create table if not exists public.link_clicks (id bigint generated always as identity primary key, link_name text not null, destination_domain text, created_at timestamptz not null default now());
create table if not exists public.site_settings (id uuid primary key default gen_random_uuid(), setting_key text unique not null, setting_value jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade);
create index if not exists page_views_created_at_idx on public.page_views(created_at);
create index if not exists page_views_path_idx on public.page_views(page_path);
create index if not exists guestbook_approved_idx on public.guestbook(is_approved, created_at desc);
create index if not exists projects_order_idx on public.projects(display_order);
alter table public.projects enable row level security;
alter table public.guestbook enable row level security;
alter table public.page_views enable row level security;
alter table public.link_clicks enable row level security;
alter table public.site_settings enable row level security;
alter table public.admin_users enable row level security;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.admin_users where user_id = auth.uid()); $$;
create policy "published projects are public" on public.projects for select using (true);
create policy "admins manage projects" on public.projects for all using (public.is_admin()) with check (public.is_admin());
create policy "approved guestbook is public" on public.guestbook for select using (is_approved = true or public.is_admin());
create policy "public can submit guestbook" on public.guestbook for insert with check (is_approved = false);
create policy "admins moderate guestbook" on public.guestbook for update using (public.is_admin()) with check (public.is_admin());
create policy "admins delete guestbook" on public.guestbook for delete using (public.is_admin());
create policy "public can record views" on public.page_views for insert with check (char_length(page_path) <= 200);
create policy "admins read views" on public.page_views for select using (public.is_admin());
create policy "public can record clicks" on public.link_clicks for insert with check (char_length(link_name) <= 80);
create policy "admins read clicks" on public.link_clicks for select using (public.is_admin());
create policy "public settings read" on public.site_settings for select using (true);
create policy "admins manage settings" on public.site_settings for all using (public.is_admin()) with check (public.is_admin());
